{
 "openapi": "3.0.3",
 "info": {
  "title": "Freya Bank voice statement services",
  "version": "2026-10-01",
  "description": "Seven POST services, JSON in/out, UTF-8. Request {data, call}; answer {data, result}. Dates dd.MM.yyyy, amounts JSON numbers. Get a bearer token first (client-credentials at tokenUrl; the test environment does not check it, send it anyway). Service names contain dots."
 },
 "servers": [
  {
   "url": "https://bank-mock.tccbank2026-yc.workers.dev/freyabank/voice/v1"
  }
 ],
 "components": {
  "securitySchemes": {
   "bankOAuth": {
    "type": "oauth2",
    "flows": {
     "clientCredentials": {
      "tokenUrl": "https://bank-mock.tccbank2026-yc.workers.dev/freyabank/oauth2/token",
      "scopes": {
       "voice.statement": "statement services"
      }
     }
    }
   }
  }
 },
 "security": [
  {
   "bankOAuth": [
    "voice.statement"
   ]
  }
 ],
 "paths": {
  "/cards.list": {
   "post": {
    "operationId": "cards.list",
    "summary": "The customer's cards the assistant may talk about",
    "description": "Start here: the phone menu hands over the customer number, there is no customer search. Only active cards (status 'A') come back; isMainCard=false for a card that is not the customer's own main card, still listed. Two cards can share productName AND cardNumberLast4 - do not assume the last four are unique. cardNumber is masked in test (first 6, last 4); send it unchanged to the other services.",
    "security": [
     {
      "bankOAuth": [
       "voice.statement"
      ]
     }
    ],
