            "messageText": {
             "type": "string",
             "description": "for logs, never read to the caller"
            },
            "code": {
             "type": "string",
             "description": "same value as returnCode"
            },
            "message": {
             "type": "string",
             "description": "same as messageText"
            },
            "type": {
             "type": [
              "string",
              "null"
             ],
             "enum": [
              "ERROR",
              "WARNING",
              null
             ]
            },
            "details": {
             "type": "object",
             "properties": {
              "guid": {
               "type": "string"
              },
              "rootCause": {
               "type": [
                "string",
                "null"
               ]
              },
              "errorOrigin": {
               "type": [
                "string",
                "null"
               ]
              }
             }
            }
